allowed:
@mixin card { .card { padding: var(--pad-card); } }
@mixin wrapper { @include card; }
@layer components { @include wrapper; }

refused:
@mixin card { .card { padding: var(--pad-card); } }
@mixin wrapper { @include card; }
@include wrapper;

allowed:
@layer reset, tokens, base, layout, components, utilities;
@layer components {
  @layer base, skin;
}
@layer components.base { .card { --card-bg: var(--bg-surface); } }
@layer components.skin { .card { --card-bg: var(--bg-sunken); } }
